class Solution:
    def perfectPairs(self, nums):
        a = sorted(abs(x) for x in nums)
        n = len(a); ans = 0; j = 0
        for i in range(n):
            if j < i + 1: j = i + 1
            while j < n and a[j] <= 2 * a[i]: j += 1
            ans += j - (i + 1)
        return ans

