class Solution {
public:
    long long perfectPairs(vector<int>& nums) {
        vector<long long> a;
        for (int x : nums) a.push_back(llabs((long long)x));
        sort(a.begin(), a.end());
        int n = a.size(); long long ans = 0; int j = 0;
        for (int i = 0; i < n; i++) {
            if (j < i + 1) j = i + 1;
            while (j < n && a[j] <= 2 * a[i]) j++;
            ans += j - (i + 1);
        }
        return ans;
    }
};

