var perfectPairs = function(nums) {
    const a = nums.map(Math.abs).sort((x, y) => x - y);
    const n = a.length; let ans = 0, j = 0;
    for (let i = 0; i < n; i++) {
        if (j < i + 1) j = i + 1;
        while (j < n && a[j] <= 2 * a[i]) j++;
        ans += j - (i + 1);
    }
    return ans;
};
